using System.ComponentModel;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var researchTools = new ResearchTools();

IList<AITool> tools =
[
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
];

IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = tools };

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Given a topic, you search the web for information,
        save important findings as notes, and then produce a final summary.

        Workflow:
        1. Search the web with several varied queries to gather diverse information.
        2. Save key findings as notes using the SaveNote tool.
        3. Retrieve all your notes with GetNotes.
        4. Write a comprehensive summary with references based on your notes.

        Always perform at least 3 different searches before summarizing.
        """),
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
];

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n📋 Research Summary\n" + new string('─', 40));
Console.WriteLine(response.Text);
Console.WriteLine(new string('─', 40));

Console.WriteLine($"\n📝 Saved Notes ({researchTools.NoteCount}):");
Console.WriteLine(researchTools.GetAllNotes());

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

sealed class ResearchTools
{
    private readonly List<(string Title, string Content)> _notes = [];
    private readonly HttpClient _http = CreateHttpClient();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information. Returns result snippets for the given query.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var json = await _http.GetStringAsync(
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1");

            var doc = JsonNode.Parse(json);
            if (doc is null) return "No results found.";

            var parts = new List<string>();

            var heading = doc["Heading"]?.GetValue<string>();
            var abstractText = doc["AbstractText"]?.GetValue<string>();
            var abstractSource = doc["AbstractSource"]?.GetValue<string>();

            if (!string.IsNullOrWhiteSpace(abstractText))
                parts.Add($"**{heading}** ({abstractSource}): {abstractText}");

            if (doc["RelatedTopics"] is JsonArray related)
            {
                foreach (var item in related.Take(6))
                {
                    var text = item?["Text"]?.GetValue<string>();
                    var url = item?["FirstURL"]?.GetValue<string>();
                    if (!string.IsNullOrWhiteSpace(text))
                        parts.Add($"- {text} ({url})");
                }
            }

            if (parts.Count == 0)
            {
                var answer = doc["Answer"]?.GetValue<string>();
                if (!string.IsNullOrWhiteSpace(answer))
                    parts.Add($"Answer: {answer}");
            }

            return parts.Count > 0
                ? string.Join("\n", parts)
                : "No relevant results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search error: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note to record an important finding.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the note")] string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0) return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"### Note {i + 1}: {n.Title}\n{n.Content}"));
    }

    private static HttpClient CreateHttpClient()
    {
        var client = new HttpClient();
        client.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
        client.Timeout = TimeSpan.FromSeconds(15);
        return client;
    }
}

